// This file is generated by AI.

// 全局样式必须在应用外壳 (`+layout.svelte`) 里被引入。
//
// 漏掉那次 import 时 `vite build` / `svelte-check` / 单测全绿, 只有界面变成裸 HTML。
// 这里刻意**不去解析构建产物**: 产物里的类名会被压缩器重写, 断言很容易变成"测压缩器行为"
// 而不是"测我们的意图"。

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

const srcDir = join(dirname(fileURLToPath(import.meta.url)), '..', 'src');

function read(relative: string): string {
  return readFileSync(join(srcDir, relative), 'utf8');
}

describe('全局样式接入', () => {
  it('应用外壳 (`+layout.svelte`) 引入了 styles.css', () => {
    const layout = read('routes/+layout.svelte');
    expect(layout, '全局样式必须在布局里引入, 否则整份界面没有样式').toMatch(/import\s+'\.\.\/styles\.css'/);
  });

  it('styles.css 定义了两套主题变量（浅色在 :root, 深色在 [data-theme]）', () => {
    const styles = read('styles.css');
    expect(styles).toContain(':root');
    expect(styles).toContain("data-theme='dark'");
    // 主题变量是外观的唯一真相来源; 少了它们所有颜色都会退回浏览器默认值
    expect(styles).toContain('--app-bg');
    expect(styles).toContain('--app-accent');
  });

  it('主题写进的是 <html data-theme>（与 styles.css 的选择器一致）', () => {
    const theme = read('lib/theme.ts');
    expect(theme).toContain("setAttribute('data-theme'");
  });
});
